VALID_OPERATORS = ("+", "-", "*", "/")
ERROR_RESULT = "Error"
OUTPUT_PRECISION = 4
EXPRESSION_PARTS = 3
RESULT_TEMPLATE = "{} = {}"
REJECTED_TEMPLATE = "{} -> rejected ({})"


def simple_calculator(num1, operator, num2):
    if operator not in VALID_OPERATORS:
        raise ValueError("unsupported operator: {!r}".format(operator))
    if operator == "+":
        return num1 + num2
    if operator == "-":
        return num1 - num2
    if operator == "*":
        return num1 * num2
    if num2 == 0:
        return ERROR_RESULT
    return num1 / num2


def to_number(token):
    value = float(token)
    if value.is_integer():
        return int(value)
    return value


def parse_expression(text):
    parts = text.split()
    if len(parts) != EXPRESSION_PARTS:
        raise ValueError(
            "expected {} fields 'num op num', got {!r}".format(EXPRESSION_PARTS, text)
        )
    return to_number(parts[0]), parts[1], to_number(parts[2])


def format_result(result):
    if isinstance(result, float):
        text = "{:.{}f}".format(result, OUTPUT_PRECISION)
        return text.rstrip("0").rstrip(".")
    return str(result)


def evaluate_line(line):
    text = line.strip()
    try:
        num1, operator, num2 = parse_expression(text)
        result = simple_calculator(num1, operator, num2)
    except ValueError as exc:
        return REJECTED_TEMPLATE.format(text, exc)
    return RESULT_TEMPLATE.format(text, format_result(result))


def main():
    import sys

    for line in sys.stdin:
        if line.strip():
            print(evaluate_line(line))


if __name__ == "__main__":
    main()

