import sys

SEED_VALUES = (0, 1)
MAX_TERMS = 100000
MAX_RETRIES = 3
TERMS_PER_ROW = 8
COLUMN_WIDTH = 12
PROMPT = "How many Fibonacci numbers? "


def fibonacci_sequence(n):
    """Return the first n Fibonacci numbers, starting with 0 and 1."""
    if n <= 0:
        return []
    sequence = list(SEED_VALUES[:n])
    while len(sequence) < n:
        sequence.append(sequence[-1] + sequence[-2])
    return sequence


def parse_term_count(raw):
    """Turn user supplied text into a valid term count."""
    text = raw.strip()
    if not text:
        raise ValueError("no term count given")
    count = int(text)
    if count < 0:
        raise ValueError("term count must not be negative")
    if count > MAX_TERMS:
        raise ValueError("term count must not exceed %d" % MAX_TERMS)
    return count


def read_term_count():
    """Ask for a term count, tolerating a few typos."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return parse_term_count(input(PROMPT))
        except ValueError as error:
            print("Invalid input (%s), attempt %d of %d." % (error, attempt, MAX_RETRIES))
    raise SystemExit("Giving up after %d attempts." % MAX_RETRIES)


def format_sequence(sequence):
    """Lay the sequence out in aligned columns."""
    rows = []
    for start in range(0, len(sequence), TERMS_PER_ROW):
        chunk = sequence[start:start + TERMS_PER_ROW]
        rows.append("".join(str(value).rjust(COLUMN_WIDTH) for value in chunk))
    return "\n".join(rows)


def main(argv):
    if len(argv) > 1:
        count = parse_term_count(argv[1])
    else:
        count = read_term_count()
    sequence = fibonacci_sequence(count)
    if sequence:
        print(format_sequence(sequence))
    else:
        print("(empty sequence)")


if __name__ == "__main__":
    main(sys.argv)

