import math
import sys

COMMENT_PREFIX = "#"
FIELD_SEPARATOR = ","
EXPECTED_FIELDS = 2
MIN_WAYPOINTS = 2
REPORT_PRECISION = 4
ORIGIN_X = 0.0
ORIGIN_Y = 0.0


def distance_2d(x1, y1, x2, y2):
    """Euclidean distance between (x1, y1) and (x2, y2)."""
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def path_length(points):
    """Total length of the polyline through a sequence of (x, y) points."""
    total = 0.0
    for (x1, y1), (x2, y2) in zip(points, points[1:]):
        total += distance_2d(x1, y1, x2, y2)
    return total


def parse_points(text):
    """Parse one 'x,y' pair per line, skipping blanks and comment lines."""
    points = []
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith(COMMENT_PREFIX):
            continue
        parts = line.split(FIELD_SEPARATOR)
        if len(parts) != EXPECTED_FIELDS:
            raise ValueError(f"line {lineno}: expected 'x,y', got {line!r}")
        try:
            points.append((float(parts[0]), float(parts[1])))
        except ValueError:
            raise ValueError(f"line {lineno}: non-numeric coordinate in {line!r}")
    if len(points) < MIN_WAYPOINTS:
        raise ValueError(f"need at least {MIN_WAYPOINTS} waypoints, got {len(points)}")
    return points


def format_report(points):
    """Render the distance of each point from the origin, then every leg and the total."""
    lines = []
    for index, (x, y) in enumerate(points, start=1):
        radius = distance_2d(ORIGIN_X, ORIGIN_Y, x, y)
        lines.append(f"point {index}: ({x}, {y}) r={radius:.{REPORT_PRECISION}f}")
    for index, ((x1, y1), (x2, y2)) in enumerate(zip(points, points[1:]), start=1):
        leg = distance_2d(x1, y1, x2, y2)
        lines.append(
            f"leg {index}: ({x1}, {y1}) -> ({x2}, {y2}) = {leg:.{REPORT_PRECISION}f}"
        )
    total = path_length(points)
    lines.append(f"total: {total:.{REPORT_PRECISION}f}")
    return "\n".join(lines)


def main(argv):
    try:
        if len(argv) > 1:
            with open(argv[1], encoding="utf-8") as handle:
                points = parse_points(handle.read())
        else:
            points = parse_points(sys.stdin.read())
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(format_report(points))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

