MAX_RETRIES = 3
DEFAULT_TIMEOUT = 0.5
MAX_TIMEOUT = 4.0
BACKOFF_FACTOR = 2.0
CURRENCY_SYMBOL = "$"
VALUE_PRECISION = 2
REPORT_WIDTH = 34


def portfolio_value(stocks, prices):
    """Total market value of {ticker: quantity} given {ticker: price}."""
    total = 0
    for ticker, quantity in stocks.items():
        if quantity < 0:
            raise ValueError("negative quantity for %s" % ticker)
        if ticker not in prices:
            raise KeyError("no price available for %s" % ticker)
        total += quantity * prices[ticker]
    return total


def format_money(value):
    return "{}{:.{}f}".format(CURRENCY_SYMBOL, value, VALUE_PRECISION)


def attempt_timeout(attempt):
    """Timeout for one quote attempt, growing geometrically up to the cap."""
    return min(
        DEFAULT_TIMEOUT * BACKOFF_FACTOR ** (attempt - 1),
        MAX_TIMEOUT,
    )


def fetch_prices(tickers, source):
    """Quote every ticker, retrying with a longer timeout after a timeout."""
    prices = {}
    for ticker in tickers:
        for attempt in range(1, MAX_RETRIES + 1):
            try:
                prices[ticker] = source(ticker, attempt_timeout(attempt))
                break
            except TimeoutError:
                if attempt == MAX_RETRIES:
                    raise TimeoutError("no quote for %s" % ticker)
    return prices


def make_feed(quotes, latencies):
    def source(ticker, timeout):
        if ticker not in quotes:
            raise KeyError("unknown ticker %s" % ticker)
        if latencies.get(ticker, 0.0) > timeout:
            raise TimeoutError(ticker)
        return quotes[ticker]
    return source


def format_report(stocks, prices):
    lines = ["PORTFOLIO".center(REPORT_WIDTH), "-" * REPORT_WIDTH]
    for ticker in sorted(stocks):
        quantity = stocks[ticker]
        amount = format_money(quantity * prices[ticker])
        label = "%s x%d @ %s" % (ticker, quantity, format_money(prices[ticker]))
        lines.append(label.ljust(REPORT_WIDTH - len(amount)) + amount)
    total = format_money(portfolio_value(stocks, prices))
    lines.append("=" * REPORT_WIDTH)
    lines.append("TOTAL".ljust(REPORT_WIDTH - len(total)) + total)
    return "\n".join(lines)


def main():
    stocks = {"AAPL": 10, "GOOG": 5, "MSFT": 12}
    quotes = {"AAPL": 150.0, "GOOG": 1000.0, "MSFT": 410.25}
    feed = make_feed(quotes, {"GOOG": DEFAULT_TIMEOUT * 1.5})
    print(format_report(stocks, fetch_prices(sorted(stocks), feed)))


if __name__ == "__main__":
    main()

