MAX_RETRIES = 5
DEFAULT_TIMEOUT = 30.0
MIN_TIMEOUT = 0.5
MAX_TIMEOUT = 120.0
BACKOFF_FACTOR = 2.0
BASE_CONFIG = {
    "host": "localhost",
    "port": 8080,
    "retries": 1,
    "timeout": DEFAULT_TIMEOUT,
}


def update_dict(dict1, dict2):
    """Merge dict2 into a copy of dict1 and return the merged dictionary."""
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("both arguments must be dictionaries")
    merged_dict = dict(dict1)
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict


def normalize_config(config):
    """Fill in missing settings and clamp them to the supported ranges."""
    normalized = dict(config)
    timeout = normalized.get("timeout")
    if timeout is None:
        timeout = DEFAULT_TIMEOUT
    timeout = float(timeout)
    if timeout <= 0:
        raise ValueError("timeout must be positive")
    normalized["timeout"] = min(max(timeout, MIN_TIMEOUT), MAX_TIMEOUT)
    retries = int(normalized.get("retries", 0))
    if retries < 0:
        raise ValueError("retries must not be negative")
    normalized["retries"] = min(retries, MAX_RETRIES)
    return normalized


def build_client_config(overrides):
    """Apply user overrides on top of the base configuration."""
    return normalize_config(update_dict(BASE_CONFIG, overrides))


def retry_plan(config):
    """Return the per-attempt timeout budget, growing with exponential backoff."""
    plan = []
    timeout = config["timeout"]
    for attempt in range(config["retries"] + 1):
        plan.append(round(min(timeout * BACKOFF_FACTOR ** attempt, MAX_TIMEOUT), 2))
    return plan


def format_config(config):
    lines = ["{0} = {1!r}".format(key, config[key]) for key in sorted(config)]
    lines.append("retries used: {0} of {1}".format(config["retries"], MAX_RETRIES))
    if config["timeout"] > DEFAULT_TIMEOUT:
        lines.append("warning: timeout exceeds the default of {0}s".format(DEFAULT_TIMEOUT))
    lines.append("attempt budgets: {0}".format(retry_plan(config)))
    return "\n".join(lines)


def main():
    print(update_dict({"a": 1, "b": 2}, {"b": 3, "c": 4}))
    print(update_dict({"x": 10}, {"y": 20}))
    config = build_client_config({"host": "api.example.com", "retries": 9, "timeout": 45})
    print(format_config(config))


if __name__ == "__main__":
    main()

