SHAPE_ERROR = "row counts differ: {} vs {}"
ROW_SHAPE_ERROR = "column counts differ in row {}: {} vs {}"


def parse_number(token):
    try:
        return int(token)
    except ValueError:
        return float(token)


def parse_matrix(block):
    rows = []
    for line in block.split(ROW_SEPARATOR):
        if line.strip():
            rows.append([parse_number(token) for token in line.split()])
    return rows


def parse_matrices(text):
    blocks = [block for block in text.split(BLOCK_SEPARATOR) if block.strip()]
    if len(blocks) != 2:
        raise ValueError("expected two matrices separated by a blank line")
    return parse_matrix(blocks[0]), parse_matrix(blocks[1])


