def format_matrix(matrix):
    lines = [format_row(row) for row in matrix[:MAX_PREVIEW_ROWS]]
    hidden = len(matrix) - MAX_PREVIEW_ROWS
    if hidden > 0:
        lines.append(TRUNCATION_NOTICE.format(hidden))
    return ROW_SEPARATOR.join(lines)


