def validate_image(image_matrix):
    if not image_matrix or not all(image_matrix):
        raise ValueError("image must contain at least one pixel")
    width = len(image_matrix[0])
    for row in image_matrix:
        if len(row) != width:
            raise ValueError("all rows must have the same width")
        for pixel in row:
            if len(pixel) != CHANNEL_COUNT:
                raise ValueError("each pixel needs %d channels" % CHANNEL_COUNT)
            for value in pixel:
                if not MIN_CHANNEL_VALUE <= value <= MAX_CHANNEL_VALUE:
                    raise ValueError(
                        "channel out of range %d..%d"
                        % (MIN_CHANNEL_VALUE, MAX_CHANNEL_VALUE)
                    )


def average_channels(pixel):
    return sum(pixel) // CHANNEL_COUNT


def to_grayscale(image_matrix):
