import sys
import time

FIELD_DELIMITER = ","
LINE_ENDINGS = "\r\n"
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0
RETRY_BACKOFF = DEFAULT_TIMEOUT / (MAX_RETRIES + 1)
COLUMN_PADDING = 2


def parse_csv_line(csv_line):
    """Split one line of unquoted CSV data into a list of field strings."""
    if not isinstance(csv_line, str):
        raise TypeError("csv_line must be a str, got %s" % type(csv_line).__name__)
    stripped = csv_line.rstrip(LINE_ENDINGS)
    if stripped == "":
        return []
    return [field.strip() for field in stripped.split(FIELD_DELIMITER)]


def read_line_with_retry(source, timeout=DEFAULT_TIMEOUT):
    """Call source() for the next raw line, retrying transient read errors."""
    deadline = time.monotonic() + timeout
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return source()
        except OSError as exc:
            if attempt == MAX_RETRIES or time.monotonic() + RETRY_BACKOFF >= deadline:
                raise TimeoutError(
                    "read failed after %d of %d attempt(s): %s"
                    % (attempt, MAX_RETRIES, exc)
                )
            time.sleep(RETRY_BACKOFF)


def collect_rows(source, timeout=DEFAULT_TIMEOUT):
    """Read lines from source until exhausted and parse each one into a row."""
    rows = []
    while True:
        raw = read_line_with_retry(source, timeout)
        if raw == "":
            return rows
        row = parse_csv_line(raw)
        if row:
            rows.append(row)


def format_table(rows):
    """Render parsed rows as a padded, column-aligned text table."""
    sizes = [0] * max(len(row) for row in rows)
    for row in rows:
        for index, field in enumerate(row):
            sizes[index] = max(sizes[index], len(field))
    lines = []
    for row in rows:
        cells = [
            field.ljust(sizes[index] + COLUMN_PADDING)
            for index, field in enumerate(row)
        ]
        lines.append("".join(cells).rstrip())
    return "\n".join(lines)


def main():
    try:
        rows = collect_rows(sys.stdin.readline)
    except TimeoutError as exc:
        print("input error: %s" % exc, file=sys.stderr)
        return 1
    if not rows:
        print("no CSV data on stdin", file=sys.stderr)
        return 1
    print(format_table(rows))
    print("%d row(s), %d field(s) total" % (len(rows), sum(map(len, rows))))
    return 0


if __name__ == "__main__":
    sys.exit(main())

