import datetime
import sys

DATE_FORMAT = "%Y-%m-%d"
DAYS_PER_WEEK = 7
EXIT_OK = 0
EXIT_INVALID_DATE = 1
EXIT_USAGE_ERROR = 2


def days_since(year, month, day):
    """Number of full days between the given past date and today."""
    past = datetime.date(year, month, day)
    today = datetime.date.today()
    if past > today:
        raise ValueError("%s is in the future" % past.strftime(DATE_FORMAT))
    return (today - past).days


def parse_date_argument(text):
    """Turn a YYYY-MM-DD string into a (year, month, day) tuple."""
    parsed = datetime.datetime.strptime(text.strip(), DATE_FORMAT).date()
    return parsed.year, parsed.month, parsed.day


def pluralize(count, noun):
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")


def describe_span(days):
    """Render a day count as weeks and days for readability."""
    if days < DAYS_PER_WEEK:
        return pluralize(days, "day")
    weeks = days // DAYS_PER_WEEK
    leftover = days % DAYS_PER_WEEK
    if leftover == 0:
        return pluralize(weeks, "week")
    return "%s and %s" % (pluralize(weeks, "week"), pluralize(leftover, "day"))


def format_report(year, month, day):
    elapsed = days_since(year, month, day)
    label = datetime.date(year, month, day).strftime(DATE_FORMAT)
    return "%s: %d (%s)" % (label, elapsed, describe_span(elapsed))


def main(argv):
    if len(argv) < 2:
        print("usage: %s DATE [DATE ...], dates written as %s" % (argv[0], DATE_FORMAT))
        return EXIT_USAGE_ERROR
    exit_code = EXIT_OK
    for argument in argv[1:]:
        try:
            print(format_report(*parse_date_argument(argument)))
        except ValueError as error:
            print("%s: %s" % (argument, error), file=sys.stderr)
            exit_code = EXIT_INVALID_DATE
    return exit_code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

