import sys
import time

DELIMITER = ","
LINE_TERMINATORS = "\r\n"
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0
RETRY_BACKOFF = 0.25
COLUMN_SEPARATOR = " | "


def parse_csv_line(line):
    """Split a single CSV row into a list of field strings."""
    if not isinstance(line, str):
        raise TypeError("line must be a string")
    return line.rstrip(LINE_TERMINATORS).split(DELIMITER)


def parse_csv_text(text):
    """Parse a whole CSV document into a list of field lists."""
    return [parse_csv_line(line) for line in text.splitlines() if line.strip()]


def read_csv_file(path, timeout=DEFAULT_TIMEOUT, max_retries=MAX_RETRIES):
    """Read a CSV file, retrying transient I/O failures within a time budget."""
    deadline = time.monotonic() + timeout
    for attempt in range(1, max_retries + 1):
        try:
            with open(path, encoding="utf-8") as handle:
                return handle.read()
        except OSError:
            remaining = deadline - time.monotonic()
            if attempt == max_retries or remaining <= 0:
                raise
            time.sleep(min(RETRY_BACKOFF * attempt, remaining))


def normalize_rows(rows):
    """Pad every row to the widest row so the table stays rectangular."""
    width = max((len(row) for row in rows), default=0)
    return [row + [""] * (width - len(row)) for row in rows]


def format_rows(rows):
    """Render parsed rows as an aligned text table."""
    rows = normalize_rows(rows)
    widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]
    lines = []
    for row in rows:
        cells = [field.ljust(widths[i]) for i, field in enumerate(row)]
        lines.append(COLUMN_SEPARATOR.join(cells).rstrip())
    return "\n".join(lines)


def main(argv):
    if len(argv) < 2:
        text = sys.stdin.read()
    else:
        timeout = float(argv[2]) if len(argv) > 2 else DEFAULT_TIMEOUT
        if timeout <= 0:
            raise ValueError("timeout must be positive")
        try:
            text = read_csv_file(argv[1], timeout=timeout)
        except OSError as exc:
            print("failed after %d attempts: %s" % (MAX_RETRIES, exc), file=sys.stderr)
            return 1
    rows = parse_csv_text(text)
    if not rows:
        print("no data rows found", file=sys.stderr)
        return 1
    print(format_rows(rows))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

