import sys
import time
import urllib.error
import urllib.request

MIN_QUANTITY = 0
CHANGE_SEPARATOR = ":"
COMMENT_PREFIX = "#"
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0
RETRY_BACKOFF_SECONDS = 0.5
RETRY_DELAYS = tuple(
    RETRY_BACKOFF_SECONDS * attempt
    for attempt in range(1, MAX_RETRIES)
)
LOW_STOCK_THRESHOLD = 3
LOW_STOCK_MARKER = " low"
REPORT_TITLE = " INVENTORY "
REPORT_RULE_CHAR = "-"
REPORT_WIDTH = 30


def update_inventory(inventory, item_name, quantity_change):
    """Apply quantity_change to item_name, never dropping below zero."""
    inventory[item_name] = max(
        MIN_QUANTITY,
        inventory.get(item_name, MIN_QUANTITY) + quantity_change,
    )
    return inventory


def parse_change_line(line):
    """Parse a feed line such as 'apple:+5' into ('apple', 5)."""
    name, separator, raw_change = line.partition(CHANGE_SEPARATOR)
    if not separator or not name.strip():
        raise ValueError("expected 'item%squantity'" % CHANGE_SEPARATOR)
    return name.strip(), int(raw_change.strip())


def apply_changes(inventory, lines):
    """Apply every valid change line to inventory; return how many applied."""
    applied = 0
    for lineno, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith(COMMENT_PREFIX):
            continue
        try:
            item_name, quantity_change = parse_change_line(stripped)
        except ValueError as exc:
            print("line %d: skipped (%s)" % (lineno, exc), file=sys.stderr)
            continue
        update_inventory(inventory, item_name, quantity_change)
        applied += 1
    return applied


def fetch_changes(url, timeout=DEFAULT_TIMEOUT):
    """Download a change feed, retrying transient network failures."""
    for attempt in range(MAX_RETRIES):
        try:
            with urllib.request.urlopen(url, timeout=timeout) as response:
                return response.read().decode("utf-8").splitlines()
        except (urllib.error.URLError, OSError):
            if attempt == len(RETRY_DELAYS):
                raise
            time.sleep(RETRY_DELAYS[attempt])


def format_report(inventory):
    """Render the inventory as a sorted table, flagging depleted stock."""
    lines = [REPORT_TITLE.center(REPORT_WIDTH, REPORT_RULE_CHAR)]
    for item_name in sorted(inventory):
        quantity = inventory[item_name]
        marker = LOW_STOCK_MARKER if quantity <= LOW_STOCK_THRESHOLD else ""
        lines.append("%-18s%6d%s" % (item_name, quantity, marker))
    lines.append(REPORT_RULE_CHAR * REPORT_WIDTH)
    return "\n".join(lines)


def main(argv):
    inventory = {"apple": 10, "banana": 5, "cherry": 2}
    if len(argv) > 1:
        changes = fetch_changes(argv[1])
    else:
        changes = sys.stdin.read().splitlines()
    applied = apply_changes(inventory, changes)
    print(format_report(inventory))
    print("applied %d change(s)" % applied)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

