import sys

MAX_SUGGESTIONS = 3
MAX_EDIT_DISTANCE = 3
BUILTIN_VOCABULARY = ("kitten", "sitting", "flaw", "lawn", "kitchen", "mitten", "law", "flow", "fawn")
DEFAULT_WORDS = ("kitten", "flaw")
REPORT_SEPARATOR = ", "


def levenshtein_distance(s1, s2):
    """Minimum number of insertions, deletions or substitutions turning s1 into s2."""
    if len(s1) < len(s2):
        s1, s2 = s2, s1
    previous = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1, start=1):
        current = [i]
        for j, c2 in enumerate(s2, start=1):
            deletion = previous[j] + 1
            insertion = current[j - 1] + 1
            substitution = previous[j - 1] + (0 if c1 == c2 else 1)
            current.append(min(deletion, insertion, substitution))
        previous = current
    return previous[-1]


def closest_words(word, vocabulary, limit=MAX_SUGGESTIONS, cutoff=MAX_EDIT_DISTANCE):
    """Return up to `limit` vocabulary entries within `cutoff` edits of `word`."""
    scored = []
    for entry in vocabulary:
        if entry == word:
            continue
        distance = levenshtein_distance(word, entry)
        if distance <= cutoff:
            scored.append((entry, distance))
    scored.sort(key=lambda pair: (pair[1], pair[0]))
    return scored[:limit]


def parse_vocabulary(text):
    """Turn whitespace-separated text into a sorted tuple of unique lowercase words."""
    return tuple(sorted({token.lower() for token in text.split()}))


def format_report(word, vocabulary):
    """Build a one-line summary of the nearest vocabulary entries for `word`."""
    suggestions = closest_words(word, vocabulary)
    if not suggestions:
        return "{0}: no word within {1} edits".format(word, MAX_EDIT_DISTANCE)
    parts = ["{0} ({1})".format(entry, distance) for entry, distance in suggestions]
    return "{0} -> {1}".format(word, REPORT_SEPARATOR.join(parts))


def main(argv):
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
            vocabulary = parse_vocabulary(handle.read())
    else:
        vocabulary = BUILTIN_VOCABULARY
    words = argv[2:] or list(DEFAULT_WORDS)
    for word in words:
        print(format_report(word.lower(), vocabulary))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

